// --- PlayerGfxTblOffsets --------------------------------------------------
// action -> FRAMES offset. Indexed by the code ProcessPlayerAction picks, +8 for
// small (GetGfxOffsetAdder). Small can neither crouch nor throw fireballs, so
// those two slots reuse the killed / standing frames.
export const GFX_TBL_OFFSETS = [
  0x20, 0x28, 0xc8, 0x18, 0x00, 0x40, 0x50, 0x58,   // big:   jump swim stand skid walk climb crouch throw
  0x80, 0x88, 0xb8, 0x78, 0x60, 0xa0, 0xb0, 0xb8,   // small: same order
];

// --- SwimKickTileNum ------------------------------------------------------
// Mario's swim-kick feet, patched over OAM row 3's left tile every 8th frame
// while swimming (PlayerGfxHandler -> BigKTS). Not reachable from FRAMES.
export const SWIM_KICK_TILES = [0x31, 0x46];  // [big, small]

// --- PlayerColors ---------------------------------------------------------
// NES palette *indices*, 4 per palette. Entry 0 is the backdrop; for sprites
// index 0 is transparent regardless of what it holds.
export const PLAYER_COLORS = [
  [0x22, 0x16, 0x27, 0x18],  // mario's colors
  [0x22, 0x30, 0x27, 0x19],  // luigi's colors
  [0x22, 0x37, 0x27, 0x16],  // fiery (used by both)
];

// --- area palettes --------------------------------------------------------
// Pre-baked PPU writes: each table opens `$3f, <lo>, <len>` -- write <len> bytes
// to that PPU address -- then the payload, then $00 to end the block. $3F00 is
// palette RAM: $3F00-$3F0F are the 4 background palettes, $3F10-$3F1F the 4
// sprite palettes, 4 entries each.
//
// The four 32-byte tables are whole sets; the short ones patch a slice.
